            if (args.Key() != winrt::Windows::System::VirtualKey::Enter) return;
            args.Handled(true);
            if (auto state = weakState.lock()) {
                BetterPanelUpdateTextSearch(
                    state, (GetKeyState(VK_SHIFT) & 0x8000) ? -1 : 1, false);
            }
